import{_ as n,o as i,c as e,a2 as t}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Hukum Perlindungan Lingkungan","description":"","frontmatter":{},"headers":[],"relativePath":"id/0046-环境保护法.md","filePath":"id/0046-环境保护法.md"}'),u={name:"id/0046-环境保护法.md"};function g(l,a,s,r,k,d){return i(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="hukum-perlindungan-lingkungan" tabindex="-1">Hukum Perlindungan Lingkungan <a class="header-anchor" href="#hukum-perlindungan-lingkungan" aria-label="Permalink to &quot;Hukum Perlindungan Lingkungan&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Proyek</th><th>Konten</th></tr></thead><tbody><tr><td>Nomor dokumen</td><td>46</td></tr><tr><td>Modul</td><td>Sistem Hukum dan Kerangka Tata Kelola</td></tr><tr><td>Kata kunci utama</td><td>Perlindungan Lingkungan, Asal Usul Alam Semesta, Simbiosis Ekologis, Pembangunan Berkelanjutan, Pencegahan dan Pengendalian Pencemaran</td></tr></tbody></table><h2 id="i-tujuan-legislasi-dan-prinsip-dasar" tabindex="-1">I. Tujuan Legislasi dan Prinsip Dasar <a class="header-anchor" href="#i-tujuan-legislasi-dan-prinsip-dasar" aria-label="Permalink to &quot;I. Tujuan Legislasi dan Prinsip Dasar&quot;">​</a></h2><p>《Hukum Perlindungan Lingkungan》 adalah salah satu dari lima hukum pendukung peradaban simbiosis jangkar, bertujuan untuk melindungi lingkungan ekologis dan asal usul alam semesta Hengyuanzhou, menetapkan konsep tata kelola lingkungan &quot;evolusi simbiosis, pembangunan berkelanjutan&quot;, mencegah kerusakan ekosistem alam semesta akibat eksploitasi predator, dan melindungi dasar kelangsungan hidup untuk kemajuan bersama semua ras.</p><p>Hukum ini menetapkan prinsip dasar berikut:</p><table tabindex="0"><thead><tr><th>Prinsip</th><th>Isi</th></tr></thead><tbody><tr><td>Prinsip Perlindungan Asal Usul</td><td>Asal usul alam semesta adalah dasar dari semua kehidupan dan evolusi, harus dilindungi dengan prioritas, dan eksploitasi destruktif dilarang</td></tr><tr><td>Prinsip Simbiosis Ekologis</td><td>Manusia dan alam, setiap ras dan ekosistem berada dalam hubungan simbiosis, dan merusak ekologi berarti merusak dasar kelangsungan hidup sendiri</td></tr><tr><td>Prinsip Keberlanjutan</td><td>Semua kegiatan eksploitasi harus mempertimbangkan kepentingan generasi sekarang dan masa depan, menentang eksploitasi berlebihan</td></tr><tr><td>Prinsip Pencegahan sebagai Utama</td><td>Perlindungan lingkungan mengutamakan pencegahan, membangun sistem penilaian dampak lingkungan, dan mencegah terjadinya pencemaran</td></tr><tr><td>Prinsip Tanggung Jawab Pencemar</td><td>Subjek yang menyebabkan pencemaran lingkungan dan kerusakan ekologi harus memikul tanggung jawab pengolahan dan ganti rugi</td></tr><tr><td>Prinsip Partisipasi Publik</td><td>Mendorong partisipasi publik dalam perlindungan lingkungan, menjamin hak publik atas informasi lingkungan dan hak partisipasi</td></tr><tr><td>Prinsip Kerja Sama Antar Bidang</td><td>Perlindungan lingkungan berlangsung melalui kerja sama antar bidang, membangun mekanisme kerja sama tata kelola lingkungan antar bidang</td></tr></tbody></table><h2 id="ii-ruang-lingkup-perlindungan-lingkungan" tabindex="-1">II. Ruang Lingkup Perlindungan Lingkungan <a class="header-anchor" href="#ii-ruang-lingkup-perlindungan-lingkungan" aria-label="Permalink to &quot;II. Ruang Lingkup Perlindungan Lingkungan&quot;">​</a></h2><p>Ruang lingkup lingkungan yang dilindungi oleh hukum ini mencakup semua ekosistem dan elemen lingkungan di dalam Hengyuanzhou:</p><ol><li><strong>Lingkungan Atmosfer</strong>: Termasuk atmosfer setiap planet, konsentrasi energi dan keseimbangan komposisi lapisan energi.</li><li><strong>Lingkungan Perairan</strong>: Termasuk kualitas dan kuantitas air permukaan, air tanah, laut, dan perairan energi antar bidang.</li><li><strong>Lingkungan Tanah</strong>: Termasuk kualitas dan kesuburan tanah daratan dan urat tambang sumber daya kultivasi.</li><li><strong>Keanekaragaman Hayati</strong>: Termasuk perlindungan spesies dan habitat semua hewan dan tumbuhan, mikroorganisme, dan kehidupan aneh.</li><li><strong>Lingkungan Energi</strong>: Termasuk konsentrasi dan keseimbangan distribusi energi spiritual langit dan bumi, energi asal usul, dan pecahan hukum.</li><li><strong>Lingkungan Ruang</strong>: Termasuk stabilitas ruang bidang, retakan ruang, dan keamanan lingkungan ruang terlipat.</li><li><strong>Lingkungan Domain Kesadaran</strong>: Termasuk kebersihan informasi ruang kesadaran kolektif dan pencegahan serta pengendalian pencemaran spiritual.</li></ol><h2 id="iii-sistem-utama" tabindex="-1">III. Sistem Utama <a class="header-anchor" href="#iii-sistem-utama" aria-label="Permalink to &quot;III. Sistem Utama&quot;">​</a></h2><h3 id="_1-sistem-penilaian-dampak-lingkungan" tabindex="-1">(1) Sistem Penilaian Dampak Lingkungan <a class="header-anchor" href="#_1-sistem-penilaian-dampak-lingkungan" aria-label="Permalink to &quot;(1) Sistem Penilaian Dampak Lingkungan&quot;">​</a></h3><p>Semua proyek pengembangan dan konstruksi yang mungkin memiliki dampak signifikan terhadap lingkungan harus menjalani penilaian dampak lingkungan sebelum dimulainya pekerjaan. Isi penilaian mencakup: dampak proyek terhadap elemen lingkungan seperti atmosfer, air, tanah, organisme, energi, ruang, dll., langkah-langkah pencegahan dan mitigasi, penilaian risiko lingkungan, dll. Proyek yang tidak lulus penilaian dampak lingkungan tidak boleh memulai konstruksi.</p><h3 id="_2-sistem-izin-pembuangan-dan-pengendalian-jumlah-total" tabindex="-1">(2) Sistem Izin Pembuangan dan Pengendalian Jumlah Total <a class="header-anchor" href="#_2-sistem-izin-pembuangan-dan-pengendalian-jumlah-total" aria-label="Permalink to &quot;(2) Sistem Izin Pembuangan dan Pengendalian Jumlah Total&quot;">​</a></h3><p>Negara menerapkan manajemen izin dan pengendalian jumlah total untuk pembuangan polutan. Unit pembuangan polusi harus mendapatkan izin pembuangan polusi, dan membuang polutan sesuai dengan jenis, konsentrasi, dan jumlah total yang ditentukan dalam izin. Negara menentukan jumlah total pembuangan polutan setiap wilayah dan setiap bidang sesuai dengan daya dukung lingkungan, dan memecahnya serta melaksanakannya secara bertahap.</p><h3 id="_3-sistem-garis-merah-perlindungan-ekologi" tabindex="-1">(3) Sistem Garis Merah Perlindungan Ekologi <a class="header-anchor" href="#_3-sistem-garis-merah-perlindungan-ekologi" aria-label="Permalink to &quot;(3) Sistem Garis Merah Perlindungan Ekologi&quot;">​</a></h3><p>Negara menetapkan garis merah perlindungan ekologi di wilayah dengan nilai ekologis khusus, termasuk:</p><table tabindex="0"><thead><tr><th>Jenis Garis Merah</th><th>Isi Perlindungan</th></tr></thead><tbody><tr><td>Wilayah Perlindungan Asal Usul</td><td>Wilayah produksi inti energi asal usul alam semesta, semua kegiatan eksploitasi dilarang</td></tr><tr><td>Habitat Spesies</td><td>Habitat inti spesies langka dan terancam punah, perusakan dan gangguan dilarang</td></tr><tr><td>Wilayah Penghalang Ekologi</td><td>Ekosistem kunci yang menjaga keseimbangan ekologis wilayah, eksploitasi dibatasi</td></tr><tr><td>Tanah Suci Kultivasi</td><td>Wilayah kaya energi dengan nilai kultivasi khusus, menerapkan pemanfaatan protektif</td></tr><tr><td>Zona Perbatasan Bidang</td><td>Zona transisi ekologis antar bidang, eksploitasi destruktif ruang dilarang</td></tr></tbody></table><h3 id="_4-sistem-pemantauan-dan-peringatan-lingkungan" tabindex="-1">(4) Sistem Pemantauan dan Peringatan Lingkungan <a class="header-anchor" href="#_4-sistem-pemantauan-dan-peringatan-lingkungan" aria-label="Permalink to &quot;(4) Sistem Pemantauan dan Peringatan Lingkungan&quot;">​</a></h3><p>Negara membangun jaringan pemantauan lingkungan yang mencakup seluruh alam semesta, memantau secara real-time perubahan setiap elemen lingkungan. Untuk kemungkinan kejadian pencemaran lingkungan parah dan kerusakan ekologi, membangun mekanisme peringatan, merilis informasi peringatan tepat waktu, dan memulai respons darurat.</p><h3 id="_5-sistem-kompensasi-ekologi" tabindex="-1">(5) Sistem Kompensasi Ekologi <a class="header-anchor" href="#_5-sistem-kompensasi-ekologi" aria-label="Permalink to &quot;(5) Sistem Kompensasi Ekologi&quot;">​</a></h3><p>Wilayah dan kelompok yang eksploitasinya dibatasi karena perlindungan lingkungan berhak menerima kompensasi ekologi. Dana kompensasi ekologi ditanggung dari akumulasi publik dan pendapatan eksploitasi sumber daya, dan digunakan untuk pengembangan ekonomi wilayah kompensasi serta peningkatan kehidupan penduduk.</p><h2 id="iv-regulasi-lingkungan-kegiatan-kultivasi" tabindex="-1">IV. Regulasi Lingkungan Kegiatan Kultivasi <a class="header-anchor" href="#iv-regulasi-lingkungan-kegiatan-kultivasi" aria-label="Permalink to &quot;IV. Regulasi Lingkungan Kegiatan Kultivasi&quot;">​</a></h2><p>Dampak kegiatan kultivasi terhadap lingkungan adalah bidang khusus dari perlindungan lingkungan Hengyuanzhou, dan hukum ini secara khusus menetapkan klausul regulasi:</p><ol><li><strong>Regulasi Eksploitasi Energi</strong>: Eksploitasi sumber daya kultivasi harus memenuhi prinsip keberlanjutan, dan eksploitasi destruktif yang menyebabkan kehabisan energi dilarang. Jumlah eksploitasi tidak boleh melebihi kecepatan pemulihan alami energi wilayah.</li><li><strong>Pengolahan Limbah Kultivasi</strong>: Sisa energi, pil kultivasi terbuang, instrumen rusak, dll. yang dihasilkan selama proses kultivasi harus diolah sesuai ketentuan, dan pembuangan sembarangan yang menyebabkan pencemaran energi dilarang.</li><li><strong>Penilaian Lingkungan Kultivasi Tingkat Lanjut</strong>: Terobosan dan penyendiran kultivator tingkat lanjut dapat memiliki dampak signifikan terhadap lingkungan sekitar, dan harus menjalani penilaian lingkungan terlebih dahulu serta mengambil langkah-langkah perlindungan.</li><li><strong>Izin Eksploitasi Bidang</strong>: Eksploitasi bidang baru harus melalui penilaian lingkungan dan investigasi ekologi, dan hanya dapat dilakukan setelah menyusun rencana perlindungan ekologi.</li><li><strong>Perlindungan Habitat Kehidupan Aneh</strong>: Habitat kehidupan aneh dimasukkan ke dalam garis merah perlindungan ekologi, dan eksplorasi serta eksploitasi tanpa izin dilarang.</li></ol><h2 id="v-tanggung-jawab-hukum" tabindex="-1">V. Tanggung Jawab Hukum <a class="header-anchor" href="#v-tanggung-jawab-hukum" aria-label="Permalink to &quot;V. Tanggung Jawab Hukum&quot;">​</a></h2><p>Kegiatan yang melanggar ketentuan hukum ini menanggung tanggung jawab berikut sesuai tingkat keparahan pelanggaran:</p><ul><li>Memulai konstruksi tanpa lulus penilaian dampak lingkungan, diperintahkan menghentikan konstruksi, memulihkan keadaan semula, dan didenda.</li><li>Membuang polutan melebihi standar, diperintahkan mengolah dalam batas waktu dan didenda, dalam kasus parah diperintahkan menutup usaha.</li><li>Merusak garis merah perlindungan ekologi, diperintahkan memulihkan keadaan semula dan didenda, dalam kasus parah dituntut tanggung jawab pidana.</li><li>Eksploitasi destruktif sumber daya kultivasi, menyita keuntungan ilegal dan didenda, mencabut izin eksploitasi.</li><li>Menyebabkan kecelakaan pencemaran lingkungan parah, menanggung tanggung jawab ganti rugi, jika构成 kejahatan dituntut tanggung jawab pidana.</li><li>Personel pengawas lingkungan yang lalai, menyalahgunakan wewenang, diberikan hukuman, jika构成 kejahatan dituntut tanggung jawab pidana.</li></ul><h2 id="vi-partisipasi-publik-dan-gugatan-kepentingan-umum-lingkungan" tabindex="-1">VI. Partisipasi Publik dan Gugatan Kepentingan Umum Lingkungan <a class="header-anchor" href="#vi-partisipasi-publik-dan-gugatan-kepentingan-umum-lingkungan" aria-label="Permalink to &quot;VI. Partisipasi Publik dan Gugatan Kepentingan Umum Lingkungan&quot;">​</a></h2><p>Publik berhak berpartisipasi dalam perlindungan lingkungan, dan saluran spesifik meliputi:</p><ol><li>Memberikan pendapat dan saran terhadap proyek penilaian dampak lingkungan.</li><li>Melaporkan dan mengadu terhadap perilaku yang mencemari lingkungan dan merusak ekologi.</li><li>Mendirikan organisasi perlindungan lingkungan sesuai hukum, berpartisipasi dalam pengawasan lingkungan dan kegiatan kepentingan umum.</li><li>Terhadap perilaku yang mencemari lingkungan, merusak ekologi, dan merugikan kepentingan umum, organisasi perlindungan lingkungan dapat mengajukan gugatan kepentingan umum lingkungan ke Pengadilan Simbiosis.</li></ol><h2 id="penutup" tabindex="-1">Penutup <a class="header-anchor" href="#penutup" aria-label="Permalink to &quot;Penutup&quot;">​</a></h2><p>《Hukum Perlindungan Lingkungan》 adalah jaminan hukum dari konsep pembangunan berkelanjutan peradaban simbiosis jangkar. Dengan membangun sistem seperti penilaian dampak lingkungan, garis merah perlindungan ekologi, dan pengendalian jumlah total, ia mengintegrasikan perlindungan lingkungan ke dalam semua kegiatan eksploitasi dan kultivasi, memastikan keberlanjutan asal usul alam semesta dan ekosistem, serta melindungi dasar kelangsungan hidup yang abadi untuk kemajuan bersama semua ras.</p><h2 id="dokumen-terkait" tabindex="-1">Dokumen terkait <a class="header-anchor" href="#dokumen-terkait" aria-label="Permalink to &quot;Dokumen terkait&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Prinsip Umum Konstitusi Simbiosis)</li><li>39-住房与环境保障 (Jaminan Perumahan dan Lingkungan)</li><li>15-能量循环与转化法则 (Hukum Siklus dan Transformasi Energi)</li><li>53-奇特生命识别标准 (Standar Identifikasi Kehidupan Aneh)</li></ul>',34)])])}const o=n(u,[["render",g]]);export{p as __pageData,o as default};
